CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;


DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260907144257_InitialCreate') THEN
    CREATE TABLE "Barrios" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Nombre" text NOT NULL,
        "Municipio" text NOT NULL,
        "Departamento" text NOT NULL,
        "Pais" text NOT NULL,
        "ZonaTransporte" text NOT NULL,
        CONSTRAINT "PK_Barrios" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260907144257_InitialCreate') THEN
    CREATE TABLE "Clientes" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Codigo" text NOT NULL,
        "Tratamiento" text NOT NULL,
        "NombreNegocio" text NOT NULL,
        "RazonSocialExtendida" text NOT NULL,
        "NombreCompleto" text NOT NULL,
        "Nombres" text NOT NULL,
        "Apellidos" text NOT NULL,
        "TipoDocumento" text NOT NULL,
        "NumeroDocumento" text NOT NULL,
        "DigitoVerificacion" integer,
        "Telefono" text,
        "Celular" text,
        "Email" text,
        "EsRural" boolean NOT NULL,
        "DireccionRural" text,
        "ViaTipo" text,
        "ViaNumero" text,
        "ViaLetra" text,
        "ViaCardinalidad" text,
        "CruceNumero" text,
        "PlacaNumero" text,
        "DireccionEstandarizada" text NOT NULL,
        "Barrio" text NOT NULL,
        "Municipio" text NOT NULL,
        "Departamento" text NOT NULL,
        "Pais" text NOT NULL,
        "ZonaTransporte" text,
        "Centro" text NOT NULL,
        "Estrato" integer NOT NULL,
        "ClaseImpuesto" text NOT NULL,
        "CondicionPago" text NOT NULL,
        "Bloqueado" boolean NOT NULL,
        "FechaRetiro" timestamp with time zone,
        "FechaCreacion" timestamp with time zone NOT NULL,
        "FechaModificacion" timestamp with time zone,
        CONSTRAINT "PK_Clientes" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260907144257_InitialCreate') THEN
    CREATE TABLE "ClientesCanalModerno" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "TipoDocumento" text NOT NULL,
        "NumeroDocumento" text NOT NULL,
        "NombreCadena" text NOT NULL,
        CONSTRAINT "PK_ClientesCanalModerno" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

