DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260907144257_InitialCreate') THEN
    CREATE UNIQUE INDEX "IX_Clientes_Codigo" ON "Clientes" ("Codigo");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260907144257_InitialCreate') THEN
    CREATE INDEX "IX_Clientes_NumeroDocumento" ON "Clientes" ("NumeroDocumento");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260907144257_InitialCreate') THEN
    PERFORM setval(
        pg_get_serial_sequence('"Barrios"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "Barrios") + 1,
            nextval(pg_get_serial_sequence('"Barrios"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"Clientes"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "Clientes") + 1,
            nextval(pg_get_serial_sequence('"Clientes"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"ClientesCanalModerno"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "ClientesCanalModerno") + 1,
            nextval(pg_get_serial_sequence('"ClientesCanalModerno"', 'Id'))),
        false);
    END IF;
END $EF$;

